assignment.solutionCode:
function deposit(amount) {
  if (amount <= 0) {
    throw new Error("Deposit must be positive.");
  }
  return amount;
}

function tryDeposit(amount) {
  try {
    return deposit(amount);
  } catch (err) {
    return err.message;
  }
}

console.log(tryDeposit(50));
console.log(tryDeposit(-10));

